// The Feed and Folders panes render the same thing: a flat list of visible
// folder/note rows derived from a nested tree. This module owns that shape —
// building the rows from any NavigationNode tree, and moving the selection
// through them with the arrow keys. Folder trees and feed buckets share it.
import type { VisibleNavigationItem } from "@typenotes/shared/types";
import type { NavigationNode } from "./types";

export function buildVisibleNavigationItems(
  nodes: NavigationNode[],
  expanded: Set<string>,
  includeNotes: boolean
): VisibleNavigationItem[] {
  const items: VisibleNavigationItem[] = [];

  const walk = (level: NavigationNode[], parentId: string | null) => {
    level.forEach((node) => {
      items.push({
        type: "folder",
        id: node.id,
        parentId,
      });

      const noteRows = includeNotes ? node.notes ?? [] : [];
      const hasNestedItems = node.children.length > 0 || noteRows.length > 0;
      if (!hasNestedItems || !expanded.has(node.id)) {
        return;
      }

      noteRows.forEach((note) => {
        items.push({
          type: "note",
          id: note.path,
          parentId: node.id,
        });
      });

      walk(node.children, node.id);
    });
  };

  walk(nodes, null);
  return items;
}

export type NavigationKey = "ArrowUp" | "ArrowDown" | "ArrowLeft" | "ArrowRight";

export type NavigateVisibleItemsDeps = {
  items: VisibleNavigationItem[];
  /**
   * Selection anchors, most specific first; the first one present in `items`
   * is the row navigation starts from (falling back to the first row).
   */
  preferredIds: Array<string | null>;
  expanded: Set<string>;
  hasNestedItems: (folderId: string) => boolean;
  expand: (folderId: string) => void;
  collapse: (folderId: string) => void;
  selectFolder: (folderId: string) => void;
  selectNote: (notePath: string, parentId: string) => void;
};

/**
 * Arrow-key navigation over a visible-rows list: up/down move the selection,
 * right expands a folder (then enters its first child), left collapses (then
 * climbs to the parent). Notes jump back to their parent folder on left.
 */
export function navigateVisibleItems(
  key: NavigationKey,
  {
    items,
    preferredIds,
    expanded,
    hasNestedItems,
    expand,
    collapse,
    selectFolder,
    selectNote,
  }: NavigateVisibleItemsDeps
): void {
  if (items.length === 0) {
    return;
  }
  const navIds = items.map((item) => item.id);
  const current =
    preferredIds.find((id): id is string => Boolean(id && navIds.includes(id))) ??
    navIds[0];
  const currentIndex = navIds.indexOf(current);
  const currentEntry = items[currentIndex];
  if (!currentEntry) {
    return;
  }

  const selectEntry = (entry: VisibleNavigationItem) => {
    if (entry.type === "folder") {
      selectFolder(entry.id);
      return;
    }
    selectNote(entry.id, entry.parentId);
  };

  if (key === "ArrowUp" || key === "ArrowDown") {
    const delta = key === "ArrowUp" ? -1 : 1;
    const nextIndex = Math.max(0, Math.min(items.length - 1, currentIndex + delta));
    const nextEntry = items[nextIndex];
    if (nextEntry) {
      selectEntry(nextEntry);
    }
    return;
  }

  if (key === "ArrowRight") {
    if (currentEntry.type !== "folder" || !hasNestedItems(currentEntry.id)) {
      return;
    }
    if (!expanded.has(currentEntry.id)) {
      expand(currentEntry.id);
      return;
    }
    const firstChildEntry = items[currentIndex + 1];
    if (!firstChildEntry || firstChildEntry.parentId !== currentEntry.id) {
      return;
    }
    selectEntry(firstChildEntry);
    return;
  }

  // ArrowLeft
  if (currentEntry.type === "note") {
    selectFolder(currentEntry.parentId);
    return;
  }
  if (hasNestedItems(currentEntry.id) && expanded.has(currentEntry.id)) {
    collapse(currentEntry.id);
    return;
  }
  const parentId = currentEntry.parentId;
  if (!parentId) {
    return;
  }
  collapse(parentId);
  selectFolder(parentId);
}
import { describe, expect, it, vi } from "vitest";

import type { NavigationNode } from "./types";
import {
  buildVisibleNavigationItems,
  navigateVisibleItems,
  type NavigateVisibleItemsDeps,
  type NavigationKey,
} from "./visible-navigation";

const note = (path: string) => ({ name: path.split("/").pop() || path, path });

const tree: NavigationNode[] = [
  {
    id: "personal",
    name: "personal",
    children: [
      { id: "personal/journal", name: "journal", children: [], notes: [note("personal/journal/a.md")] },
    ],
    notes: [note("personal/todo.md")],
  },
  { id: "work", name: "work", children: [], notes: [] },
];

describe("buildVisibleNavigationItems", () => {
  it("lists only top-level folders when nothing is expanded", () => {
    const items = buildVisibleNavigationItems(tree, new Set(), true);
    expect(items.map((item) => item.id)).toEqual(["personal", "work"]);
  });

  it("interleaves notes before child folders for expanded branches", () => {
    const items = buildVisibleNavigationItems(
      tree,
      new Set(["personal", "personal/journal"]),
      true
    );
    expect(items.map((item) => `${item.type}:${item.id}`)).toEqual([
      "folder:personal",
      "note:personal/todo.md",
      "folder:personal/journal",
      "note:personal/journal/a.md",
      "folder:work",
    ]);
    expect(items[1].parentId).toBe("personal");
  });

  it("emits folder-only rows when notes are excluded", () => {
    const items = buildVisibleNavigationItems(tree, new Set(["personal"]), false);
    expect(items.map((item) => item.id)).toEqual([
      "personal",
      "personal/journal",
      "work",
    ]);
    expect(items.every((item) => item.type === "folder")).toBe(true);
  });

  it("does not descend into an expanded folder with no visible rows", () => {
    const items = buildVisibleNavigationItems(tree, new Set(["work"]), false);
    expect(items.map((item) => item.id)).toEqual(["personal", "work"]);
  });
});

describe("navigateVisibleItems", () => {
  type DepsOverrides = Partial<
    Pick<NavigateVisibleItemsDeps, "items" | "preferredIds" | "expanded">
  >;

  const makeDeps = (overrides: DepsOverrides = {}) => ({
    items: buildVisibleNavigationItems(tree, new Set(["personal"]), true),
    preferredIds: [] as Array<string | null>,
    expanded: new Set(["personal"]),
    hasNestedItems: (id: string) => id === "personal" || id === "personal/journal",
    expand: vi.fn<(folderId: string) => void>(),
    collapse: vi.fn<(folderId: string) => void>(),
    selectFolder: vi.fn<(folderId: string) => void>(),
    selectNote: vi.fn<(notePath: string, parentId: string) => void>(),
    ...overrides,
  });

  const navigate = (key: NavigationKey, deps: NavigateVisibleItemsDeps) =>
    navigateVisibleItems(key, deps);

  it("starts from the first matching preferred id", () => {
    const deps = makeDeps({
      preferredIds: [null, "missing", "personal/journal"],
    });
    navigate("ArrowDown", deps);
    expect(deps.selectFolder).toHaveBeenCalledWith("work");
  });

  it("falls back to the first row and clamps at the top edge", () => {
    const deps = makeDeps();
    navigate("ArrowUp", deps);
    expect(deps.selectFolder).toHaveBeenCalledWith("personal");
  });

  it("moves down onto a note row", () => {
    const deps = makeDeps({ preferredIds: ["personal"] });
    navigate("ArrowDown", deps);
    expect(deps.selectNote).toHaveBeenCalledWith("personal/todo.md", "personal");
  });

  it("expands a collapsed folder on ArrowRight", () => {
    const deps = makeDeps({
      items: buildVisibleNavigationItems(tree, new Set(), true),
      expanded: new Set(),
      preferredIds: ["personal"],
    });
    navigate("ArrowRight", deps);
    expect(deps.expand).toHaveBeenCalledWith("personal");
    expect(deps.selectFolder).not.toHaveBeenCalled();
  });

  it("enters the first child of an expanded folder on ArrowRight", () => {
    const deps = makeDeps({ preferredIds: ["personal"] });
    navigate("ArrowRight", deps);
    expect(deps.selectNote).toHaveBeenCalledWith("personal/todo.md", "personal");
  });

  it("ignores ArrowRight on a folder without nested rows", () => {
    const deps = makeDeps({ preferredIds: ["work"] });
    navigate("ArrowRight", deps);
    expect(deps.expand).not.toHaveBeenCalled();
    expect(deps.selectFolder).not.toHaveBeenCalled();
    expect(deps.selectNote).not.toHaveBeenCalled();
  });

  it("jumps from a note back to its parent folder on ArrowLeft", () => {
    const deps = makeDeps({ preferredIds: ["personal/todo.md"] });
    navigate("ArrowLeft", deps);
    expect(deps.selectFolder).toHaveBeenCalledWith("personal");
    expect(deps.collapse).not.toHaveBeenCalled();
  });

  it("collapses an expanded folder on ArrowLeft", () => {
    const deps = makeDeps({ preferredIds: ["personal"] });
    navigate("ArrowLeft", deps);
    expect(deps.collapse).toHaveBeenCalledWith("personal");
    expect(deps.selectFolder).not.toHaveBeenCalled();
  });

  it("climbs to the parent, collapsing it, when the folder itself has no open rows", () => {
    const deps = makeDeps({ preferredIds: ["personal/journal"] });
    navigate("ArrowLeft", deps);
    expect(deps.collapse).toHaveBeenCalledWith("personal");
    expect(deps.selectFolder).toHaveBeenCalledWith("personal");
  });

  it("does nothing on ArrowLeft at a collapsed top-level folder", () => {
    const deps = makeDeps({
      items: buildVisibleNavigationItems(tree, new Set(), true),
      expanded: new Set(),
      preferredIds: ["personal"],
    });
    navigate("ArrowLeft", deps);
    expect(deps.collapse).not.toHaveBeenCalled();
    expect(deps.selectFolder).not.toHaveBeenCalled();
  });
});
import { FolderPlusIcon, FolderIcon } from "lucide-react";

import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/shared/ui/command";
import type { SettingsSectionId } from "@/features/settings/lib/sections";
import { useCommandPaletteCommands } from "../hooks/use-command-palette-commands";

type CommandPaletteProps = {
  onOpenSettings: (section: SettingsSectionId) => void;
  onOpenFeed: () => void;
  onOpenArchive: () => void;
  onNewRecording: () => void;
  onImportHandwriting: () => void;
};

/**
 * Context-aware command palette (⌘K / Ctrl+K). The hook owns the live command
 * list and state; this component renders either the normal command list or the
 * terminal-style `mv <path>` folder picker.
 */
export function CommandPalette({
  onOpenSettings,
  onOpenFeed,
  onOpenArchive,
  onNewRecording,
  onImportHandwriting,
}: CommandPaletteProps) {
  const {
    open,
    setOpen,
    inputValue,
    setInputValue,
    closePalette,
    groups,
    runCommand,
    moveMode,
    runMove,
    completePath,
  } = useCommandPaletteCommands({
    onOpenSettings,
    onOpenFeed,
    onOpenArchive,
    onNewRecording,
    onImportHandwriting,
  });

  return (
    <CommandDialog
      open={open}
      onOpenChange={(nextOpen) => {
        if (nextOpen) {
          setOpen(true);
        } else {
          closePalette();
        }
      }}
      // In move mode we render our own folder suggestions, so let cmdk show them
      // verbatim instead of fuzzy-filtering against the "mv …" input.
      shouldFilter={!moveMode}
    >
      <CommandInput
        placeholder={
          moveMode ? "mv <folder> — Tab to drill in, Enter to move" : "Type a command or search…"
        }
        value={inputValue}
        onValueChange={setInputValue}
        onKeyDown={(event) => {
          if (!moveMode || event.key !== "Tab") {
            return;
          }
          // Tab completes the highlighted folder so you can keep navigating.
          event.preventDefault();
          const active = document.querySelector<HTMLElement>(
            '[cmdk-item][aria-selected="true"][data-folder-path]'
          );
          const path = active?.getAttribute("data-folder-path");
          if (path) {
            completePath(path);
          }
        }}
      />
      <CommandList>
        {moveMode ? (
          <>
            <CommandEmpty>
              {moveMode.noteCount === 0
                ? "Open or select a note first."
                : "No matching folders. Keep typing to create one."}
            </CommandEmpty>
            {moveMode.noteCount > 0 && moveMode.rows.length > 0 ? (
              <CommandGroup
                heading={
                  moveMode.noteCount > 1
                    ? `Move ${moveMode.noteCount} notes to…`
                    : "Move note to…"
                }
              >
                {moveMode.rows.map((row) => {
                  const Icon =
                    row.kind === "create" ? FolderPlusIcon : FolderIcon;
                  return (
                    <CommandItem
                      key={`${row.kind}:${row.path}`}
                      value={`${row.kind}:${row.path}`}
                      data-folder-path={row.kind === "folder" ? row.path : undefined}
                      onSelect={() => runMove(row.path)}
                    >
                      <Icon className="text-muted-foreground" />
                      <span className="truncate">{row.label}</span>
                      {row.kind === "folder" && row.sublabel !== row.label ? (
                        <span className="text-muted-foreground ml-auto truncate text-xs">
                          {row.sublabel}
                        </span>
                      ) : null}
                    </CommandItem>
                  );
                })}
              </CommandGroup>
            ) : null}
          </>
        ) : (
          <>
            <CommandEmpty>No matching commands.</CommandEmpty>
            {groups.map((group) => (
              <CommandGroup key={group.heading} heading={group.heading}>
                {group.items.map((command) => {
                  const Icon = command.icon;
                  return (
                    <CommandItem
                      key={command.id}
                      keywords={command.keywords}
                      onSelect={() => runCommand(command)}
                    >
                      <Icon className="text-muted-foreground" />
                      <span>{command.label}</span>
                    </CommandItem>
                  );
                })}
              </CommandGroup>
            ))}
          </>
        )}
      </CommandList>
    </CommandDialog>
  );
}
import { useEffect, useMemo, useState, type ComponentType } from "react";
import { useShallow } from "zustand/react/shallow";
import {
  ArchiveIcon,
  DownloadIcon,
  FilePlusIcon,
  FolderInputIcon,
  ImageIcon,
  InboxIcon,
  MicIcon,
  MoonIcon,
  PencilIcon,
  SettingsIcon,
  SunIcon,
  Trash2Icon,
} from "lucide-react";

import { useSelection } from "@/app/state/selection-store";
import { useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
import { useAppearance } from "@/app/state/appearance-store";
import { FEED_FOLDER_PATH, isSystemFolder } from "@typenotes/shared/constants";
import { collectFolderPaths, getNoteParentPath } from "@typenotes/shared/notes";
import type { SettingsSectionId } from "@/features/settings/lib/sections";
import {
  buildFolderSuggestions,
  folderExists,
  parseMoveCommand,
  type FolderSuggestion,
} from "../lib/folder-search";

type CommandPaletteProps = {
  onOpenSettings: (section: SettingsSectionId) => void;
  onOpenFeed: () => void;
  onOpenArchive: () => void;
  onNewRecording: () => void;
  onImportHandwriting: () => void;
};

type PaletteCommand = {
  id: string;
  label: string;
  icon: ComponentType<{ className?: string }>;
  keywords?: string[];
  /** When true, running the command leaves the palette open (e.g. entering move mode). */
  keepOpen?: boolean;
  run: () => void;
};

type PaletteGroup = {
  heading: string;
  items: PaletteCommand[];
};

/** A single row rendered while the `mv` terminal command is active. */
export type MoveRow =
  | { kind: "folder"; path: string; label: string; sublabel: string }
  | { kind: "create"; path: string; label: string };

export type MoveMode = {
  query: string;
  noteCount: number;
  rows: MoveRow[];
};

type UseCommandPaletteCommandsArgs = CommandPaletteProps;

const folderName = (path: string) => path.split("/").pop() || path;

export function useCommandPaletteCommands({
  onOpenSettings,
  onOpenFeed,
  onOpenArchive,
  onNewRecording,
  onImportHandwriting,
}: UseCommandPaletteCommandsArgs) {
  const [open, setOpen] = useState(false);
  const [inputValue, setInputValue] = useState("");

  const { selectedNotes, selectedFolders, activeNote, activeFolder } = useSelection(
    useShallow((state) => ({
      selectedNotes: state.selectedNotes,
      selectedFolders: state.selectedFolders,
      activeNote: state.activeNote,
      activeFolder: state.activeFolder,
    }))
  );
  const {
    tree,
    createNewNote,
    deleteNotes,
    deleteFolders,
    moveNotesToArchive,
    moveNotesToFolder,
    flattenIntoFeed,
    updateNoteMarkers,
    startRenameFolder,
    allNotePreviews,
  } = useNotesTree();
  const { theme, setTheme } = useAppearance(
    useShallow((state) => ({
      theme: state.theme,
      setTheme: state.setTheme,
    }))
  );

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") {
        event.preventDefault();
        setOpen((prev) => !prev);
      }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, []);

  const noteTargets = useMemo(
    () =>
      selectedNotes.size > 0
        ? Array.from(selectedNotes)
        : activeNote
          ? [activeNote]
          : [],
    [selectedNotes, activeNote]
  );
  const folderTargets = Array.from(selectedFolders);
  const removableFolders = folderTargets.filter((path) => !isSystemFolder(path));
  const notesOutsideFeed = noteTargets.filter(
    (path) => getNoteParentPath(path) !== FEED_FOLDER_PATH
  );
  const canFlatten = removableFolders.length > 0 || notesOutsideFeed.length > 0;
  const allArchived =
    noteTargets.length > 0 && noteTargets.every((path) => allNotePreviews[path]?.isArchived);
  const allReviewed =
    noteTargets.length > 0 && noteTargets.every((path) => allNotePreviews[path]?.isReviewed);

  const allFolderPaths = useMemo(() => collectFolderPaths(tree), [tree]);

  // --- Terminal `mv` command -------------------------------------------------
  const parsedMove = parseMoveCommand(inputValue);

  const enterMoveMode = () => setInputValue("mv ");

  const runMove = (destinationPath: string) => {
    if (noteTargets.length === 0 || !destinationPath.trim()) {
      return;
    }
    void moveNotesToFolder(noteTargets, destinationPath);
    setOpen(false);
    setInputValue("");
  };

  /** Tab-completion: drill into a folder by appending it (with a trailing "/"). */
  const completePath = (path: string) => setInputValue(`mv ${path}/`);

  const moveMode = useMemo<MoveMode | null>(() => {
    if (!parsedMove) {
      return null;
    }
    const { query } = parsedMove;
    const stripped = query.replace(/^\/+/, "");
    const core = stripped.replace(/\/+$/, "");
    const endsWithSlash = stripped.endsWith("/");

    const rows: MoveRow[] = [];

    // "Move into this folder" when we've drilled into an existing directory.
    if (endsWithSlash && core && folderExists(allFolderPaths, core)) {
      rows.push({
        kind: "folder",
        path: core,
        label: `Move into "${folderName(core)}"`,
        sublabel: core,
      });
    }

    // "Create & move" when the typed path is not an existing folder.
    if (core && !folderExists(allFolderPaths, core)) {
      rows.push({
        kind: "create",
        path: core,
        label: `Create & move to "${core}"`,
      });
    }

    const suggestions: FolderSuggestion[] = buildFolderSuggestions(allFolderPaths, query);
    for (const suggestion of suggestions) {
      // Avoid duplicating the "move into" context row.
      if (suggestion.path === core && endsWithSlash) {
        continue;
      }
      rows.push({
        kind: "folder",
        path: suggestion.path,
        label: suggestion.name,
        sublabel: suggestion.path,
      });
    }

    return { query, noteCount: noteTargets.length, rows };
  }, [parsedMove, allFolderPaths, noteTargets.length]);

  // --- Normal command list ---------------------------------------------------
  const selectionCommands: PaletteCommand[] = [];
  if (noteTargets.length > 0) {
    selectionCommands.push({
      id: "move-notes-folder",
      label:
        noteTargets.length > 1
          ? `Move ${noteTargets.length} notes to folder…`
          : "Move note to folder…",
      icon: FolderInputIcon,
      keywords: ["move", "mv", "folder", "destination"],
      keepOpen: true,
      run: enterMoveMode,
    });
    selectionCommands.push({
      id: "toggle-archive",
      label: allArchived ? "Unarchive notes" : "Archive notes",
      icon: ArchiveIcon,
      keywords: ["archive", "hide", "review"],
      run: () =>
        void updateNoteMarkers(noteTargets, {
          archived: allArchived ? null : true,
        }),
    });
    selectionCommands.push({
      id: "toggle-reviewed",
      label: allReviewed ? "Mark notes unreviewed" : "Mark notes reviewed",
      icon: PencilIcon,
      keywords: ["reviewed", "done", "checked"],
      run: () =>
        void updateNoteMarkers(noteTargets, {
          reviewed: allReviewed ? null : true,
        }),
    });
    selectionCommands.push({
      id: "archive-notes",
      label: `Archive ${noteTargets.length} note${noteTargets.length > 1 ? "s" : ""}`,
      icon: ArchiveIcon,
      keywords: ["move", "archive", "trash"],
      run: () => void moveNotesToArchive(noteTargets),
    });
    selectionCommands.push({
      id: "delete-notes",
      label: `Delete ${noteTargets.length} note${noteTargets.length > 1 ? "s" : ""}`,
      icon: Trash2Icon,
      keywords: ["remove"],
      run: () => void deleteNotes(noteTargets),
    });
  }
  if (canFlatten) {
    selectionCommands.push({
      id: "flatten-into-feed",
      label:
        removableFolders.length > 0
          ? `Flatten ${removableFolders.length} folder${removableFolders.length > 1 ? "s" : ""} into Feed`
          : `Move ${notesOutsideFeed.length} note${notesOutsideFeed.length > 1 ? "s" : ""} into Feed`,
      icon: FolderInputIcon,
      keywords: ["flatten", "move", "feed", "collapse"],
      run: () => void flattenIntoFeed(folderTargets, noteTargets),
    });
  }
  if (folderTargets.length === 1 && !isSystemFolder(folderTargets[0])) {
    const folder = folderTargets[0];
    selectionCommands.push({
      id: "new-note-in-folder",
      label: `New note in "${folderName(folder)}"`,
