import { APP_EXTENSIONS } from "@/features/extensions/registry";

export type SettingsSectionId =
  | "general"
  | "profile"
  | "import"
  | "sync"
  | "updates"
  | "appearance"
  | "transcription"
  | "recordings"
  | "security";

export type SettingsSection = {
