    const onInvalidated = () => {
      cacheRef.current.clear();
      setRefreshToken((value) => value + 1);
    };
    window.addEventListener("note-previews-invalidated", onInvalidated);
    return () => window.removeEventListener("note-previews-invalidated", onInvalidated);
